public final class Account {
    private final ReentrantLock gate = new ReentrantLock(true);  // fair
    private long balance;

    public Lock gate() { return gate; }          // published lock

    public void transferTo(Account to, long amount) {
        gate.lock();
        try {
            to.gate().lock();                    // fixed order: this, then to
            try { balance -= amount; to.balance += amount; }
            finally { to.gate().unlock(); }
        } finally { gate.unlock(); }
    }
}
